const API="/api/v1"; const params=new URLSearchParams(location.search); const businessId=params.get("business_id"); const bookingToken=params.get("booking_token"); const rescheduleToken=params.get("reschedule_token"); const state={business:null,slots:[],selected:null,managed:null}; const $=(id)=>document.getElementById(id); const today=()=>new Intl.DateTimeFormat("en-CA",{timeZone:"America/Sao_Paulo"}).format(new Date());
const money=(cents)=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(cents/100); const time=(value)=>new Intl.DateTimeFormat("pt-BR",{hour:"2-digit",minute:"2-digit",timeZone:state.business?.timezone||"America/Sao_Paulo"}).format(new Date(value));
async function request(path,options={}){const response=await fetch(`${API}${path}`,options);const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.detail||"Não foi possível concluir.");return data}
async function boot(){if(bookingToken){await loadManagedBooking();return}if(!businessId){showPageError("O link de agendamento está incompleto.");return}try{if(rescheduleToken){state.managed=await request(`/public/businesses/appointments/${rescheduleToken}`);if(!["scheduled","confirmed"].includes(state.managed.status))throw new Error("Este agendamento não pode mais ser alterado.")}state.business=await request(`/public/businesses/${businessId}`);$("business-name").textContent=state.business.name;$("service").innerHTML='<option value="">Selecione</option>'+state.business.services.map(s=>`<option value="${s.id}">${s.name} · ${s.duration_minutes} min · ${money(s.price_cents)}</option>`).join("");$("barber").innerHTML='<option value="">Selecione</option>'+state.business.barbers.map(b=>`<option value="${b.id}">${b.full_name}</option>`).join("");$("date").min=today();$("date").value=today();if(rescheduleToken){$("customer-fields").hidden=true;$("name").required=false;$("phone").required=false;$("submit").firstElementChild.textContent="Confirmar novo horário";document.querySelector(".intro>p").textContent="REAGENDAR ATENDIMENTO"}$("booking-card").hidden=false}catch(error){showPageError(error.message)}}
function showPageError(message){$("business-name").textContent="Agendamento indisponível";$("page-error-message").textContent=message;$("page-error").hidden=false}
async function loadSlots(){state.selected=null;$("submit").disabled=true;const barber=$("barber").value,date=$("date").value,service=state.business.services.find(s=>s.id===$("service").value);if(!barber||!date||!service){$("slots").innerHTML="";$("slot-help").textContent="Selecione serviço, profissional e data.";return}$("slot-help").textContent="Carregando horários...";try{const data=await request(`/public/businesses/${businessId}/barbers/${barber}/availability?appointment_date=${date}`);const duration=service.duration_minutes*60000;state.slots=data.slots.filter(slot=>{const start=new Date(slot.starts_at).getTime(),target=start+duration;let cursor=start;for(const candidate of data.slots){if(new Date(candidate.starts_at).getTime()===cursor)cursor=new Date(candidate.ends_at).getTime();if(cursor>=target)return true}return false});renderSlots()}catch(error){$("slot-help").textContent=error.message;$("slots").innerHTML=""}}
function renderSlots(){$("slot-help").textContent=state.slots.length?"Clique em um horário para selecionar.":"Nenhum horário disponível nesta data.";$("slots").innerHTML=state.slots.map((slot,index)=>`<button type="button" class="slot" data-index="${index}">${time(slot.starts_at)}</button>`).join("")}
$("slots").addEventListener("click",event=>{const button=event.target.closest("[data-index]");if(!button)return;document.querySelectorAll(".slot").forEach(item=>item.classList.remove("selected"));button.classList.add("selected");state.selected=state.slots[Number(button.dataset.index)];$("submit").disabled=false});
[$("service"),$("barber"),$("date")].forEach(input=>input.addEventListener("change",loadSlots));
$("booking-form").addEventListener("submit",async event=>{event.preventDefault();if(!state.selected)return;$("error").textContent="";$("submit").disabled=true;$("submit").firstElementChild.textContent="Confirmando...";try{const basePayload={barber_id:$("barber").value,service_id:$("service").value,starts_at:state.selected.starts_at};const result=rescheduleToken?await request(`/public/businesses/appointments/${rescheduleToken}/reschedule`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(basePayload)}):await request(`/public/businesses/${businessId}/appointments`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...basePayload,customer_name:$("name").value.trim(),customer_phone:$("phone").value.trim(),notes:$("notes").value.trim()||null})});$("booking-card").hidden=true;$("success-detail").textContent=`${result.service_name} com ${result.barber_name}, em ${new Date(result.starts_at).toLocaleDateString("pt-BR",{timeZone:state.business.timezone})} às ${time(result.starts_at)}.`;$("cancellation-link").value=`${location.origin}/dashboard/booking/?booking_token=${rescheduleToken||result.booking_token}`;$("success").hidden=false;$("success").querySelector("h2").textContent=rescheduleToken?"Novo horário confirmado!":"Seu horário está reservado!";scrollTo({top:0,behavior:"smooth"})}catch(error){$("error").textContent=error.message;await loadSlots()}finally{$("submit").firstElementChild.textContent=rescheduleToken?"Confirmar novo horário":"Confirmar agendamento"}});
async function loadManagedBooking(){try{state.managed=await request(`/public/businesses/appointments/${bookingToken}`);$("business-name").textContent=state.managed.business_name;$("manage").hidden=false;renderManagedBooking()}catch(error){showPageError(error.message)}}
function renderManagedBooking(){const active=["scheduled","confirmed"].includes(state.managed.status);$("manage-icon").textContent=active?"✓":"×";$("manage-title").textContent=state.managed.status==="scheduled"?"Confirme sua presença":state.managed.status==="confirmed"?"Presença confirmada":"Agendamento cancelado";$("manage-detail").textContent=`${state.managed.service_name} com ${state.managed.barber_name}, em ${new Date(state.managed.starts_at).toLocaleDateString("pt-BR")} às ${new Date(state.managed.starts_at).toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}.`;$("reschedule-booking").hidden=!active;$("confirm-booking").hidden=state.managed.status!=="scheduled";$("cancel-booking").hidden=!active;$("cancel-booking").disabled=false}
$("copy-cancellation-link").addEventListener("click",async()=>{await navigator.clipboard.writeText($("cancellation-link").value);$("copy-cancellation-link").textContent="Link copiado!"});
$("cancel-booking").addEventListener("click",async()=>{if(!confirm("Deseja realmente cancelar este agendamento?"))return;$("cancel-booking").disabled=true;try{state.managed=await request(`/public/businesses/appointments/${bookingToken}/cancel`,{method:"PATCH"});renderManagedBooking()}catch(error){alert(error.message);$("cancel-booking").disabled=false}});
$("confirm-booking").addEventListener("click",async()=>{$("confirm-booking").disabled=true;try{state.managed=await request(`/public/businesses/appointments/${bookingToken}/confirm`,{method:"PATCH"});renderManagedBooking()}catch(error){alert(error.message);$("confirm-booking").disabled=false}});
$("reschedule-booking").addEventListener("click",()=>location.href=`${location.pathname}?business_id=${state.managed.business_id}&reschedule_token=${bookingToken}`);
$("new-booking").addEventListener("click",()=>location.href=`${location.pathname}?business_id=${businessId}`);boot();
